type Logger struct{ prefix string }
func (l *Logger) Log(msg string) { fmt.Println(l.prefix + msg) }

type Service struct {
    *Logger              // встраивание
    name string
}

s := Service{Logger: &Logger{prefix: "[svc] "}, name: "billing"}
s.Log("старт")          // продвинутый метод
s.Logger.Log("явно")

type Base struct{}
func (Base) Name() string  { return "base" }
func (b Base) Hello() string { return "hello from " + b.Name() }

type Child struct{ Base }
func (Child) Name() string { return "child" }

fmt.Println(Child{}.Hello())   // hello from base — не child!

